#!/usr/bin/env node
/**
 * smoke.mjs - boots the real server in mock mode on a free port, drives a full
 * scenario over HTTP + SSE, and prints PASS/FAIL per assertion.
 *
 * It never touches the project's own data/: config/, skills/, public/ and
 * workspace/ are copied into a temp directory and ASSIST_HOME points there, so a
 * green run leaves the repo exactly as it was.
 *
 * Exit code 0 = every assertion passed. Non-zero = something is broken.
 */

import { spawn } from 'node:child_process';
import fsp from 'node:fs/promises';
import fsSync from 'node:fs';
import http from 'node:http';
import os from 'node:os';
import path from 'node:path';
import zlib from 'node:zlib';
import { fileURLToPath } from 'node:url';

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

/**
 * Repo source, with LF endings. Assertions quote source lines, and a Windows
 * checkout (core.autocrlf=true) writes CRLF - the product is the same file.
 */
/**
 * Wait until cond() is true (checked every 20 ms, up to ms), then give its last
 * value. For checks on work that finishes a moment later: a fixed sleep passed
 * here and failed on a slower CI runner now and then (1.5.11, 1.5.19).
 */
async function until(cond, ms = 5000) {
  const end = Date.now() + ms;
  for (;;) {
    let v;
    try { v = await cond(); } catch { v = false; }
    if (v || Date.now() > end) return v;
    await new Promise((r) => setTimeout(r, 20));
  }
}

async function readText(rel) {
  // The app page is split into files (ENG-04): checks read it as one text.
  if (rel === '../public/index.html') return (await import('./page-source.mjs')).pageSource(path.join(REPO, 'public'));
  return (await fsp.readFile(new URL(rel, import.meta.url), 'utf8')).replace(/\r\n/g, '\n');
}

// ---------------------------------------------------------------------------
// tiny assertion harness
// ---------------------------------------------------------------------------

const results = [];

function record(ok, name, detail = '') {
  results.push({ ok, name, detail });
  const line = ok ? `PASS  ${name}` : `FAIL  ${name}${detail ? `  <- ${detail}` : ''}`;
  console.log(line);
  return ok;
}

function check(name, condition, detail = '') {
  return record(Boolean(condition), name, condition ? '' : detail);
}

function checkEqual(name, actual, expected) {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  return record(ok, name, ok ? '' : `expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
}

function skip(name, why) {
  console.log(`SKIP  ${name}  (${why})`);
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** Run an async fn and return the error code it throws, or null. */
async function errorCode(fn) {
  try {
    await fn();
    return null;
  } catch (err) {
    return err.code || err.message;
  }
}

/**
 * Run one scenario. A throw becomes a single FAIL instead of taking down the
 * whole run, so a smoke run always reports the full picture.
 */
async function stage(name, fn) {
  // SMOKE_ONLY=<regex>: only the stages whose name matches (a quick rerun while working).
  if (process.env.SMOKE_ONLY && !new RegExp(process.env.SMOKE_ONLY).test(name)) return;
  try {
    await fn();
  } catch (err) {
    record(false, `stage "${name}" completed without throwing`, err?.message || String(err));
  }
}

// ---------------------------------------------------------------------------
// main
// ---------------------------------------------------------------------------

let child = null;
let home = null;
let base = '';
// The harness stands for the human's own app (1.5.27): requests to the hub under
// test carry the local key, like the desktop app's. rawFetch goes without it.
const rawFetch = globalThis.fetch;
let keyDir = ''; // the data folder of the hub under test when it is not ASSIST_DATA_DIR's (a second hub)
const localKeyOf = () => { try { return fsSync.readFileSync(path.join(keyDir || process.env.ASSIST_DATA_DIR || '', 'local-key'), 'utf8').trim(); } catch { return ''; } };
globalThis.fetch = (input, init = {}) => {
  const url = typeof input === 'string' ? input : input?.url || '';
  if (base && url.startsWith(base) && (keyDir || process.env.ASSIST_DATA_DIR)) {
    const key = localKeyOf();
    const h = new Headers(init.headers || (typeof input === 'object' ? input.headers : undefined) || {});
    if (key && !h.has('x-lamplit-local') && !h.has('x-no-local-key')) h.set('x-lamplit-local', key);
    h.delete('x-no-local-key');
    return rawFetch(input, { ...init, headers: h });
  }
  return rawFetch(input, init);
};
let publicBase = '';

