    const sneak2 = await api(`/api/peers/${encodeURIComponent(peerName)}/bots/ops/..%2F..%2Fapprovals%2F${encodeURIComponent(card?.id || 'x')}`, { method: 'POST', body: { decision: 'approve' } });
